<!doctype html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>السيرة النبوية — Викторина</title>
<style>
:root {
  --bg:#071A16; --panel:#0D2A23; --gold:#E7B84B;
  --cream:#F5E8C8; --green:#159447; --border:#4A695E;
}
* { box-sizing:border-box; }
body {
  margin:0; min-height:100vh; font-family:Arial,sans-serif;
  background:linear-gradient(135deg,#071A16,#0D2A23);
  color:var(--cream);
}
.screen { min-height:100vh; display:none; padding:22px; }
.screen.active { display:flex; flex-direction:column; }
.center { align-items:center; justify-content:center; text-align:center; }
h1 { color:var(--gold); font-size:42px; margin:0 0 12px; }
h2 { font-size:28px; margin:8px 0; }
.subtitle { font-size:20px; font-weight:bold; }
.gold { color:var(--gold); }
button {
  border:0; border-radius:16px; padding:16px 20px; width:100%;
  font-size:16px; font-weight:bold; cursor:pointer; color:#000;
  background:var(--gold); margin:7px 0;
}
button.green { background:var(--green); color:white; }
button.panel { background:var(--panel); color:var(--cream); border:1px solid var(--border); text-align:left; }
button.answer { background:var(--panel); color:var(--cream); border:1px solid var(--border); text-align:left; }
button.answer.selected { background:var(--green); border-color:var(--gold); }
button:disabled { opacity:.65; cursor:default; }
.top { display:flex; align-items:center; gap:10px; }
.top button { width:auto; margin:0; padding:10px 14px; }
.progress { height:8px; background:#23443B; border-radius:8px; overflow:hidden; margin:10px 0; }
.progress > div { height:100%; background:var(--green); width:0; }
.card {
  background:var(--cream); color:#18231F; border-radius:22px;
  padding:22px; font-size:19px; font-weight:bold; text-align:center; margin:14px 0;
}
.timer { margin-left:auto; color:var(--gold); font-weight:bold; }
.timer.danger { color:#ff5555; }
.explanation { text-align:center; padding:8px; min-height:42px; }
.correct { color:#62E39B; } .wrong { color:#FF9B8F; }
.small { opacity:.75; margin-top:8px; }
#categories, #answers { margin-top:6px; }
</style>
</head>
<body>

<section id="home" class="screen active center">
  <h1>السيرة النبوية</h1>
  <div class="subtitle">ЖИЗНЕОПИСАНИЕ ПРОРОКА ﷺ</div>
  <div class="gold">МИР ЕМУ И БЛАГОСЛОВЕНИЕ АЛЛАХА</div>
  <div style="height:28px"></div>
  <button class="green" onclick="showCategories()">НАЧАТЬ ВИКТОРИНУ</button>
  <div class="small">100 сложных вопросов • 30 секунд на вопрос</div>
</section>

<section id="categories" class="screen">
  <div class="top"><button onclick="show('home')">←</button><h2>Выбор категории</h2></div>
  <div class="gold">Выберите период жизни Пророка ﷺ</div>
  <div id="categoryList"></div>
</section>

<section id="quiz" class="screen">
  <div class="top">
    <button onclick="show('home')">←</button>
    <strong id="questionNumber"></strong>
    <span class="timer" id="timer">30s</span>
  </div>
  <div class="progress"><div id="progressBar"></div></div>
  <div class="gold" id="categoryName"></div>
  <div id="scoreText"></div>
  <div class="card" id="questionText"></div>
  <div id="answers"></div>
  <div class="explanation" id="explanation"></div>
  <button id="nextBtn" disabled onclick="nextQuestion()">ДАЛЕЕ</button>
</section>

<section id="result" class="screen center">
  <h1>السيرة النبوية</h1>
  <h2>Ваш результат</h2>
  <div id="resultScore" style="font-size:54px;color:var(--gold);font-weight:bold"></div>
  <div id="resultCorrect" style="font-size:18px"></div>
  <div style="height:20px"></div>
  <button class="green" onclick="showCategories()">ВЫБРАТЬ СНОВА</button>
</section>

<script>
const questions = [{"category": "1. Детство и юность", "question": "К какому племени принадлежал Пророк Мухаммад ﷺ?", "options": ["Курайш", "Аус", "Хазрадж", "Сакиф"], "correct": 0, "explanation": "Пророк ﷺ происходил из племени Курайш."}, {"category": "1. Детство и юность", "question": "Как звали отца Пророка ﷺ?", "options": ["Абд аль-Мутталиб", "Абдуллах", "Абу Талиб", "Аббас"], "correct": 1, "explanation": "Его отца звали Абдуллах ибн Абд аль-Мутталиб."}, {"category": "1. Детство и юность", "question": "Как звали мать Пророка ﷺ?", "options": ["Амина бинт Вахб", "Халима ас-Са'дия", "Фатима бинт Асад", "Сафия"], "correct": 0, "explanation": "Мать Пророка ﷺ — Амина бинт Вахб."}, {"category": "1. Детство и юность", "question": "Как звали деда Пророка ﷺ?", "options": ["Абу Талиб", "Абд аль-Мутталиб", "Хамза", "Аббас"], "correct": 1, "explanation": "Дедом Пророка ﷺ был Абд аль-Мутталиб."}, {"category": "1. Детство и юность", "question": "Кто был молочной матерью Пророка ﷺ из племени Са'д?", "options": ["Халима ас-Са'дия", "Сувайба", "Амина", "Умм Айман"], "correct": 0, "explanation": "Халима ас-Са'дия была его известной молочной матерью."}, {"category": "1. Детство и юность", "question": "Какое качество было известно о Пророке ﷺ ещё до пророчества?", "options": ["Аль-Амин — доверенный", "Аль-Муджахид", "Аль-Халиф", "Аль-Кади"], "correct": 0, "explanation": "Его называли аль-Амин — доверенный, надёжный."}, {"category": "1. Детство и юность", "question": "С кем Пророк ﷺ вступил в брак до начала пророчества?", "options": ["Аишей", "Хадиджей бинт Хувайлид", "Хафсой", "Саудой"], "correct": 1, "explanation": "Хадиджа رضي الله عنها была его первой супругой."}, {"category": "1. Детство и юность", "question": "Сколько лет было Пророку ﷺ при первом откровении?", "options": ["30", "35", "40", "45"], "correct": 2, "explanation": "Первое откровение пришло к нему в возрасте 40 лет."}, {"category": "1. Детство и юность", "question": "Где Пророк ﷺ обычно уединялся до начала откровения?", "options": ["В пещере Хира", "В пещере Саур", "В Куба", "На Ухуде"], "correct": 0, "explanation": "Он уединялся в пещере Хира."}, {"category": "1. Детство и юность", "question": "Какой союз существовал в Мекке для защиты угнетённых и который Пророк ﷺ вспоминал положительно?", "options": ["Хильф аль-Фудуль", "Хильф аль-Муахат", "Хильф ан-Нусра", "Хильф ат-Тайф"], "correct": 0, "explanation": "Хильф аль-Фудуль был союзом для защиты справедливости."}, {"category": "1. Детство и юность", "question": "Как назывался род Пророка ﷺ внутри Курайша?", "options": ["Бану Хашим", "Бану Умайя", "Бану Тамим", "Бану Сакиф"], "correct": 0, "explanation": "Пророк ﷺ происходил из Бану Хашим."}, {"category": "1. Детство и юность", "question": "Кто из дядей Пророка ﷺ воспитывал его после смерти деда?", "options": ["Абу Талиб", "Абу Лахаб", "Хамза", "Аббас"], "correct": 0, "explanation": "После смерти Абд аль-Мутталиба его опекал Абу Талиб."}, {"category": "2. Начало пророчества", "question": "Какой ангел принёс Пророку ﷺ первое откровение?", "options": ["Микаиль", "Джибриль", "Исрафиль", "Малик"], "correct": 1, "explanation": "Первое откровение принёс Джибриль عليه السلام."}, {"category": "2. Начало пророчества", "question": "Где произошло первое откровение?", "options": ["В Хире", "В Сауре", "В Куба", "В Арафате"], "correct": 0, "explanation": "Первое откровение было в пещере Хира."}, {"category": "2. Начало пророчества", "question": "Какое слово связано с началом первого откровения?", "options": ["Икра — читай", "Укмур — повелевай", "Саллим — приветствуй", "Ускут — молчи"], "correct": 0, "explanation": "Начало откровения содержит повеление «Икра» — «Читай»."}, {"category": "2. Начало пророчества", "question": "Кто первым поддержал Пророка ﷺ после первого откровения из его семьи?", "options": ["Хадиджа رضي الله عنها", "Аиша رضي الله عنها", "Фатима رضي الله عنها", "Хафса رضي الله عنها"], "correct": 0, "explanation": "Хадиджа رضي الله عنها поддержала его и отправилась с ним к Вараке."}, {"category": "2. Начало пророчества", "question": "К кому Хадиджа رضي الله عنها отвела Пророка ﷺ после первого откровения?", "options": ["Вараке ибн Науфалю", "Абу Суфьяну", "Абу Джахлю", "Аббасу"], "correct": 0, "explanation": "Она отвела его к Вараке ибн Науфалю."}, {"category": "2. Начало пророчества", "question": "Какое откровение связано с повелением «Встань и предостерегай»?", "options": ["Аль-Муддассир", "Аль-Фатиха", "Аль-Каусар", "Ан-Наср"], "correct": 0, "explanation": "Сура аль-Муддассир содержит это обращение."}, {"category": "2. Начало пророчества", "question": "Кого Пророк ﷺ призвал открыто после периода тайного призыва?", "options": ["Курайш и жителей Мекки", "Только жителей Медины", "Только римлян", "Только жителей Йемена"], "correct": 0, "explanation": "После тайного периода призыв стал открытым в Мекке."}, {"category": "2. Начало пророчества", "question": "Как называлась гора, с которой Пророк ﷺ обратился к Курайшу с открытым призывом?", "options": ["Сафа", "Арафат", "Ухуд", "Синай"], "correct": 0, "explanation": "Пророк ﷺ обратился к Курайшу с холма ас-Сафа."}, {"category": "2. Начало пророчества", "question": "Кто был среди первых уверовавших и близких сподвижников Пророка ﷺ?", "options": ["Абу Бакр ас-Сиддик", "Абу Джахль", "Абу Лахаб", "Утба ибн Рабиа"], "correct": 0, "explanation": "Абу Бакр رضي الله عنه был одним из первых уверовавших."}, {"category": "2. Начало пророчества", "question": "Кто из членов семьи Пророка ﷺ одним из первых принял Ислам?", "options": ["Али ибн Абу Талиб", "Абу Джахль", "Утба", "Абу Суфьян"], "correct": 0, "explanation": "Али رضي الله عنه был среди первых принявших Ислам."}, {"category": "2. Начало пророчества", "question": "Куда часть первых мусульман переселилась, спасаясь от преследований?", "options": ["Абиссиния", "Шам", "Египет", "Ирак"], "correct": 0, "explanation": "Часть мусульман переселилась в Абиссинию."}, {"category": "2. Начало пророчества", "question": "Как назывался правитель Абиссинии, предоставивший убежище мусульманам?", "options": ["Ан-Наджаши", "Кисра", "Кайсар", "Мукауккис"], "correct": 0, "explanation": "Правителя Абиссинии называют ан-Наджаши."}, {"category": "3. Мекканский период", "question": "Как назывался бойкот против Бану Хашим и сторонников Пророка ﷺ?", "options": ["Бойкот в долине Абу Талиба", "Бойкот Хайбара", "Бойкот Куба", "Бойкот Табука"], "correct": 0, "explanation": "Мекканцы заключили соглашение о бойкоте Бану Хашим."}, {"category": "3. Мекканский период", "question": "Кто был дядей Пророка ﷺ и его опекуном, защищавшим его в Мекке?", "options": ["Абу Талиб", "Абу Лахаб", "Аббас", "Хамза"], "correct": 0, "explanation": "Абу Талиб защищал Пророка ﷺ в Мекке."}, {"category": "3. Мекканский период", "question": "Как назывался год, в котором умерли Хадиджа رضي الله عنها и Абу Талиб?", "options": ["Год печали", "Год победы", "Год света", "Год хиджры"], "correct": 0, "explanation": "Этот период традиционно называют Годом печали."}, {"category": "3. Мекканский период", "question": "Куда Пророк ﷺ отправился после усиления преследований в Мекке и где подвергся жестокому обращению?", "options": ["Таиф", "Хайбар", "Табук", "Наджран"], "correct": 0, "explanation": "Он отправился в Таиф с призывом."}, {"category": "3. Мекканский период", "question": "Как называется ночное путешествие Пророка ﷺ из Заповедной мечети?", "options": ["Исра", "Хиджра", "Фатх", "Бай'а"], "correct": 0, "explanation": "Ночное путешествие называется Исра."}, {"category": "3. Мекканский период", "question": "Как называется вознесение Пророка ﷺ на небеса?", "options": ["Мирадж", "Худайбия", "Му'та", "Хайбар"], "correct": 0, "explanation": "Вознесение называется Мирадж."}, {"category": "3. Мекканский период", "question": "Какое поклонение связано с событием Исра и Мирадж?", "options": ["Пять ежедневных молитв", "Закят", "Пост Ашуры", "Хадж"], "correct": 0, "explanation": "Пять ежедневных молитв были установлены в связи с этим событием."}, {"category": "3. Мекканский период", "que