асан и Хусейн", "Умар и Усман", "Зайд и Джафар"], "correct": 0, "explanation": "Среди его сыновей были аль-Касим, Абдуллах и Ибрахим."}, {"category": "8. Семья, нрав и последние годы", "question": "Как звали сына Пророка ﷺ от Марии аль-Кыбтият?", "options": ["Ибрахим", "Касим", "Абдуллах", "Хасан"], "correct": 0, "explanation": "Ибрахим был сыном Пророка ﷺ от Марии аль-Кыбтият."}, {"category": "8. Семья, нрав и последние годы", "question": "Какая супруга Пророка ﷺ известна передачей большого числа хадисов и была дочерью Абу Бакра?", "options": ["Аиша", "Хафса", "Сауда", "Умм Салама"], "correct": 0, "explanation": "Аиша رضي الله عنها была дочерью Абу Бакра и крупным передатчиком хадисов."}, {"category": "8. Семья, нрав и последние годы", "question": "Кто была дочерью Умара رضي الله عنه и супругой Пророка ﷺ?", "options": ["Хафса", "Аиша", "Сафия", "Зайнаб"], "correct": 0, "explanation": "Хафса رضي الله عنها была дочерью Умара رضي الله عنه."}, {"category": "8. Семья, нрав и последние годы", "question": "Как назывался последний хадж Пророка ﷺ?", "options": ["Прощальный хадж", "Хадж Бадра", "Хадж Хайбара", "Хадж Табука"], "correct": 0, "explanation": "Последний хадж называют Прощальным."}, {"category": "8. Семья, нрав и последние годы", "question": "Где Пророк ﷺ произнёс знаменитую проповедь во время Прощального хаджа?", "options": ["Арафат", "Ухуд", "Сафа", "Куба"], "correct": 0, "explanation": "Главная проповедь была произнесена в день Арафата."}, {"category": "8. Семья, нрав и последние годы", "question": "В каком городе Пророк ﷺ умер?", "options": ["Медина", "Мекка", "Таиф", "Куфа"], "correct": 0, "explanation": "Пророк ﷺ умер в Медине."}, {"category": "8. Семья, нрав и последние годы", "question": "Сколько лет, согласно наиболее распространённому мнению, было Пророку ﷺ при смерти?", "options": ["60", "63", "65", "70"], "correct": 1, "explanation": "Распространённое мнение — 63 года."}, {"category": "8. Семья, нрав и последние годы", "question": "Где был похоронен Пророк ﷺ?", "options": ["В комнате Аиши رضي الله عنها в Медине", "В Мекке возле Каабы", "В Куба", "На Ухуде"], "correct": 0, "explanation": "Он был похоронен там, где умер, в комнате Аиши رضي الله عنها."}, {"category": "8. Семья, нрав и последние годы", "question": "Какой сподвижник стал первым халифом после смерти Пророка ﷺ?", "options": ["Абу Бакр ас-Сиддик", "Умар", "Усман", "Али"], "correct": 0, "explanation": "После Пророка ﷺ первым халифом стал Абу Бакр رضي الله عنه."}, {"category": "8. Семья, нрав и последние годы", "question": "Какое качество Пророка ﷺ особо подчёркивает Коран в отношении его характера?", "options": ["Великая нравственность", "Богатство", "Военная сила", "Царское происхождение"], "correct": 0, "explanation": "В Коране сказано о великом нраве Пророка ﷺ."}, {"category": "8. Семья, нрав и последние годы", "question": "Какой титул означает «Посланник Аллаха»?", "options": ["Расулуллах", "Аль-Фарук", "Зун-нурайн", "Ас-Сиддик"], "correct": 0, "explanation": "Расулуллах означает «Посланник Аллаха»."}];
let active = [];
let index = 0;
let score = 0;
let selected = -1;
let seconds = 30;
let timerId = null;

const categories = [...new Set(questions.map(q => q.category))];

function show(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  if (timerId) { clearInterval(timerId); timerId = null; }
}

function showCategories() {
  show('categories');
  const box = document.getElementById('categoryList');
  box.innerHTML = '';
  const all = document.createElement('button');
  all.className = 'panel';
  all.innerHTML = '<b>Все категории</b><br><span class="gold">'+questions.length+' вопросов</span>';
  all.onclick = () => startQuiz(questions);
  box.appendChild(all);

  categories.forEach(cat => {
    const count = questions.filter(q => q.category === cat).length;
    const b = document.createElement('button');
    b.className = 'panel';
    b.innerHTML = '<b>'+escapeHtml(cat)+'</b><br><span class="gold">'+count+' вопросов</span>';
    b.onclick = () => startQuiz(questions.filter(q => q.category === cat));
    box.appendChild(b);
  });
}

function startQuiz(list) {
  active = list;
  index = 0; score = 0; selected = -1; seconds = 30;
  show('quiz');
  renderQuestion();
}

function renderQuestion() {
  if (timerId) clearInterval(timerId);
  selected = -1; seconds = 30;
  const q = active[index];

  document.getElementById('questionNumber').textContent =
    `Вопрос ${index+1} из ${active.length}`;
  document.getElementById('timer').textContent = '30s';
  document.getElementById('timer').classList.remove('danger');
  document.getElementById('progressBar').style.width =
    (((index+1)/active.length)*100)+'%';
  document.getElementById('categoryName').textContent = q.category;
  document.getElementById('scoreText').textContent = 'Счёт: '+score;
  document.getElementById('questionText').textContent = q.question;
  document.getElementById('explanation').textContent = '';
  document.getElementById('explanation').className = 'explanation';

  const answers = document.getElementById('answers');
  answers.innerHTML = '';
  q.options.forEach((option,i) => {
    const b = document.createElement('button');
    b.className = 'answer';
    b.textContent = String.fromCharCode(65+i)+'.  '+option;
    b.onclick = () => selectAnswer(i);
    answers.appendChild(b);
  });

  const next = document.getElementById('nextBtn');
  next.disabled = true;
  next.textContent = index === active.length-1 ? 'ЗАВЕРШИТЬ' : 'ДАЛЕЕ';

  timerId = setInterval(() => {
    seconds--;
    const t = document.getElementById('timer');
    t.textContent = seconds+'s';
    if (seconds <= 5) t.classList.add('danger');
    if (seconds <= 0) {
      clearInterval(timerId); timerId = null;
      revealAnswer(-1);
    }
  },1000);
}

function selectAnswer(i) {
  if (selected !== -1) return;
  revealAnswer(i);
}

function revealAnswer(i) {
  const q = active[index];
  selected = i;
  if (i === q.correct) score += 10;

  document.querySelectorAll('.answer').forEach((b,n) => {
    b.disabled = true;
    if (n === q.correct) b.classList.add('selected');
  });

  const exp = document.getElementById('explanation');
  if (i === q.correct) {
    exp.className = 'explanation correct';
    exp.textContent = '✓ Правильно! '+q.explanation;
  } else {
    exp.className = 'explanation wrong';
    exp.textContent = '✗ '+q.explanation;
  }
  document.getElementById('scoreText').textContent = 'Счёт: '+score;
  document.getElementById('nextBtn').disabled = false;
}

function nextQuestion() {
  if (index === active.length-1) {
    document.getElementById('resultScore').textContent = score+' / '+(active.length*10);
    document.getElementById('resultCorrect').textContent =
      'Правильных ответов: '+Math.floor(score/10)+' из '+active.length;
    show('result');
  } else {
    index++;
    renderQuestion();
  }
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
</script>
</body>
</html>
